-- 116_group_trainers.sql
--
-- Every stock class trainer becomes a group trainer: it trains every class of
-- its group, so a new race and class pair finds a trainer at home.
-- GENERATED by tools/gen-group-trainer-sql.js from the live tw_world on
-- 2026-10-13. Edit the generator, not this file.
--
--   Combat  Warrior, Paladin, Hunter, Rogue   (mask 15)
--   Wizard  Priest, Mage, Warlock   (mask 400)
--   Mystic  Shaman, Druid   (mask 1088), and the Earth and Fire Totems
--
-- Needs the core that reads a group trainer (Creature::IsGroupTrainer). An
-- older binary refuses a trainer with trainer_class 0 and nothing else happens.
-- Templates and npc flags load at startup: restart after applying.
--
-- 252 trainers: Combat 122, Wizard 100, Mystic 30. 249 have a menu of their own.
-- Lists: Warrior 104, Paladin 160, Hunter 126, Rogue 114, Priest 191, Shaman 178, Mage 167, Warlock 146, Druid 193.
--
-- Gaps, each filled by a trainer of our own (100033-100038 and 100040, spawn guids
-- 2950000-2950099). Move one with .npc spawn move and run the generator again:
-- it keeps a spawn where it stands. NOT .npc move, which does not save.
--   Northshire: Aleria Moonbrook <Mystic Trainer>, beside Priestess Anetta (Priest)
--   Goldshire: Aleria Moonbrook <Mystic Trainer>, beside Priestess Josetta (Priest)
--   Coldridge Valley: Oakenpaw <Mystic Trainer>, beside Branstock Khalder (Priest)
--   Kharanos: Oakenpaw <Mystic Trainer>, beside Maxan Anvol (Priest)
--   Ironforge: Oakenpaw <Mystic Trainer>, beside Toldren Deepiron (Priest)
--   High Elf start: Aleria Moonbrook <Mystic Trainer>, beside Priestess Maelah Sunsworn (Priest)
--   Alah'Thalas: Aleria Moonbrook <Mystic Trainer>, beside High Priest Raemoran Alah'belore (Priest)
--   Deathknell: Hania Earthsong <Mystic Trainer>, beside Dark Cleric Duesten (Priest)
--   Brill: Hania Earthsong <Mystic Trainer>, beside Dark Cleric Beryl (Priest)
--   Undercity: Hania Earthsong <Mystic Trainer>, beside Father Lankester (Priest)
--   Bloodhoof Village: Evelyn Ashgrave <Wizard Trainer>, beside Narm Skychaser (Shaman)
--   Blackstone Island: Hania Earthsong <Mystic Trainer>, beside Wizette Icewhistle (Mage)
--
-- Ids: npc_trainer_template 1101-1111, gossip_menu 64040-64049 and
-- 6410000-6410999, npc_text and broadcast_text 6400300-6400319,
-- conditions 6400300-6400329. The originals are in comfy_trainer_stock.
--
-- TO RESTORE the stock trainers:
--
--   UPDATE creature_template ct JOIN comfy_trainer_stock s ON s.entry = ct.entry
--     SET ct.subname = s.subname, ct.gossip_menu_id = s.gossip_menu_id, ct.npc_flags = s.npc_flags,
--         ct.trainer_class = s.trainer_class, ct.trainer_spell = s.trainer_spell, ct.trainer_id = s.trainer_id;
--   DELETE FROM npc_vendor WHERE item IN (5175, 5176) AND entry IN (SELECT entry FROM comfy_trainer_stock);
--
-- then restart.

CREATE TABLE IF NOT EXISTS comfy_trainer_stock (
  entry          mediumint(8) unsigned NOT NULL PRIMARY KEY,
  subname        char(100) DEFAULT NULL,
  gossip_menu_id mediumint(8) unsigned NOT NULL,
  npc_flags      int(10) unsigned NOT NULL,
  trainer_class  tinyint(3) unsigned NOT NULL,
  trainer_spell  mediumint(8) unsigned NOT NULL,
  trainer_id     mediumint(8) unsigned NOT NULL
) ENGINE=MyISAM COMMENT='A class trainer as it was before 116 made it a group trainer';

-- An entry an older run converted and this one does not goes back to stock.
UPDATE creature_template ct JOIN comfy_trainer_stock s ON s.entry = ct.entry
  SET ct.subname = s.subname, ct.gossip_menu_id = s.gossip_menu_id, ct.npc_flags = s.npc_flags,
      ct.trainer_class = s.trainer_class, ct.trainer_spell = s.trainer_spell, ct.trainer_id = s.trainer_id
